var n=[{title:`Lär dig rörelsen`,text:`Stå med mjuka knän. Skjut höfterna bakåt som om du stängde en bildörr med dem, och låt bålen luta framåt medan ryggen förblir i ett bekvämt, kontrollerat läge. Stanna när baksidan av låren begränsar rörelsen eller bålen inte kan hållas kontrollerad, och driv sedan höfterna framåt för att resa dig. Du tränar höftrörelse, så att nå golvet är inte målet.`},{title:`Höftgångjärn och knäböj`,text:`Båda rörelserna använder höfter och knän, med olika tonvikt. I en knäböj böjs knäna oftast mer och bålen förblir mer upprätt. I ett rumänskt marklyft böjs knäna lite och höfterna rör sig längre bakåt, vilket lägger mer arbete på kroppens baksida. En skinkbrygga tränar höftsträckning med bålen stödd och är ibland ett lättare ställe att börja.`},{title:`Övningar för inlärning`,text:`För en väggtappning, stå ett kort steg från en vägg och skjut höfterna bakåt tills de rör den. En lätt käpp som hålls längs huvudet, övre ryggen och bäckenet kan visa när ryggraden rör sig mycket. Använd de här övningarna för inlärning, och tvinga inte fram en stel hållning på grund av dem.`},{title:`Progression och misstag`,text:`Börja med repetitioner utan belastning och gå sedan över till ett lätt kettlebellmarklyft eller ett rumänskt marklyft med hantlar. Håll vikten nära och använd ett omfång du kan kontrollera. Att böja knäna för mycket förvandlar lyftet till en knäböj, och att jaga ett bestämt djup kan flytta rörelsen till ryggen. Svingar kräver mer färdighet än ett långsamt höftgångjärn.`},{title:`Så använder du TrainUp`,text:`Din plan innehåller höftgångjärnsövningar som passar din utrustning och ditt mål. Om balans eller en känslig rygg gör belastade höftgångjärn svåra är en stödd variant eller en höftbrygga ett alternativ, och du kan notera en ryggbegränsning i Profil. Om smärtan består, uppsök en läkare eller fysioterapeut i stället för att bygga en egen rehabplan.`}];var r=[{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACE: teknik för tvåhandssving med kettlebell`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`NSCA: grunder i säkerhet och styrketräning`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:n,sources:r};export{a as default,n as sections,r as sources};